login.fast_script_login:
(username, password) => {
  const userEl = document.querySelector("input[placeholder*='điện thoại'], input[placeholder*='email'], input[placeholder*='username']");
  const passEl = document.querySelector("input[type='password']");
  const submitBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Đăng nhập'));
  if (userEl && passEl) {
    userEl.value = username;
    userEl.dispatchEvent(new Event('input', { bubbles: true }));
    passEl.value = password;
    passEl.dispatchEvent(new Event('input', { bubbles: true }));
    if (submitBtn) submitBtn.click();
    return true;
  }
  return false;
}

classroom_exams.fast_script_get_uncompleted_exams:
() => {
  // Expand list first
  const viewMoreBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Xem thêm');
  if (viewMoreBtn) viewMoreBtn.click();

  const examLinks = Array.from(document.querySelectorAll("a[href*='/vi/de-thi/']"));
  const uncompleted = [];

  examLinks.forEach(link => {
    const text = link.innerText;
    if (text.includes('Chưa thi')) {
      const lines = text.split('\n').map(s => s.trim()).filter(Boolean);
      const href = link.getAttribute('href');
      const title = lines[0] || 'Đề thi';
      const timeLimit = lines.find(l => l.includes('Thời gian') || l.includes('Thi trước')) || 'Không thời hạn';
      uncompleted.push({ title, timeLimit, href, fullUrl: window.location.origin + href });
    }
  });
  return uncompleted;
}

exam_entry.fast_script_start:
() => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Bắt đầu thi');
  if (btn) { btn.click(); return true; }
  return false;
}

take_test.fast_script_extract_all:
() => {
  return {
    title: document.title,
    bodyText: document.body.innerText,
    abcdCount: Array.from(document.querySelectorAll('button')).filter(b => ['A', 'B', 'C', 'D'].includes(b.textContent.trim())).length / 4,
    tfCount: Array.from(document.querySelectorAll('button')).filter(b => ['Đúng', 'Sai'].includes(b.textContent.trim())).length / 2
  };
}

take_test.fast_script_fill_answers:
(abcdAnswers, tfAnswers) => {
  const allButtons = Array.from(document.querySelectorAll('button'));
  const abcdButtons = allButtons.filter(b => ['A', 'B', 'C', 'D'].includes(b.textContent.trim()));
  const tfButtons = allButtons.filter(b => ['Đúng', 'Sai'].includes(b.textContent.trim()));

  let abcdCount = 0;
  for (let q = 0; q < abcdAnswers.length; q++) {
    const targetChar = abcdAnswers[q];
    const qButtons = abcdButtons.slice(q * 4, q * 4 + 4);
    const btn = qButtons.find(b => b.textContent.trim() === targetChar);
    if (btn) { btn.click(); abcdCount++; }
  }

  let tfCount = 0;
  for (let item = 0; item < tfAnswers.length; item++) {
    const targetChoice = tfAnswers[item];
    const itemButtons = tfButtons.slice(item * 2, item * 2 + 2);
    const btn = itemButtons.find(b => b.textContent.trim() === targetChoice);
    if (btn) { btn.click(); tfCount++; }
  }

  return {
    abcdFilled: abcdCount,
    tfFilled: tfCount,
    totalSelected: document.querySelectorAll('.selected-answer').length
  };
}
